// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  interpolateColors,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: montserratFamily } = loadMontserrat("normal", {
  weights: ["400", "700", "900"],
});



export type RollingCounterProps = Record<string, any>;

const RollingCounter: React.FC<RollingCounterProps> = ({
  backgroundColor = "#0b101d",
  transparentBackground = false,
  durationInSeconds = 5,
  targetValue = 500,
  drumMass = 1.2,
  drumStiffness = 90,
  drumDamping = 18,
  shudderStrength = 1.0,
  startFrame = 30,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Responsive scaling based on reference 1920x1080 resolution
  const scale = width / 1920;

  // Increased face height and radius to spread out the numbers above and below further
  const faceHeight = 112 * scale;
  const radius = (faceHeight / (2 * Math.tan(Math.PI / 10))) * 1.15; // Scaled up radius to spread drums apart

  // Parse target value into a 3-digit array padded with leading zeros (for £000 to £500)
  const digitsArray = targetValue.toString().padStart(3, "0").split("").map(Number);

  // Identify where the actual number starts to keep leading zeros white and make active numbers turn red
  const firstNonZeroIndex = targetValue === 0 ? 2 : 3 - targetValue.toString().length;

  // Background color handling for transparent option
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Sound/movement shudder effect for the entire £ sign when rolling starts
  const shudderProgress = spring({
    frame: Math.max(0, frame - startFrame),
    fps,
    config: {
      mass: 0.5,
      damping: 10,
      stiffness: 160,
    },
  });

  const isRolling = frame >= startFrame;
  const rawShakeX = Math.sin(frame * 0.95) * 8 * scale * shudderStrength;
  const rawShakeY = Math.cos(frame * 1.1) * 6 * scale * shudderStrength;
  const currentShakeX = isRolling ? rawShakeX * (1 - shudderProgress) : 0;
  const currentShakeY = isRolling ? rawShakeY * (1 - shudderProgress) : 0;

  // Subtle clean shadows optimized for black drum face backgrounds
  const getShadowStyle = (p: number, isLeading: boolean) => {
    if (isLeading) {
      return `
        0 ${1 * scale}px 0 rgba(255, 255, 255, 0.1),
        0 ${2 * scale}px ${4 * scale}px rgba(0, 0, 0, 0.6)
      `;
    }
    return `
      0 ${1 * scale}px 0 rgba(255, 255, 255, 0.15),
      0 ${2 * scale}px ${5 * scale}px rgba(0, 0, 0, 0.7)
    `;
  };

  // Render vignette/glow only when background is not transparent
  const radialGlow = transparentBackground
    ? "none"
    : "radial-gradient(circle, rgba(28, 41, 74, 0.45) 0%, rgba(11, 16, 29, 0) 75%)";

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        width: "100%",
        height: "100%",
        overflow: "hidden",
        fontFamily: montserratFamily,
      }}
    >
      {!transparentBackground && (
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            background: radialGlow,
            pointerEvents: "none",
          }}
        />
      )}

      {/* Main Counter Wrapper */}
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          transform: `scale(${scale})`,
          transformOrigin: "center center",
        }}
      >
        {/* Real 3D physical-beveled £ Sign */}
        <div
          style={{
            fontSize: `${220 * scale}px`,
            fontWeight: 900,
            color: "#ede9e1",
            marginRight: `${35 * scale}px`,
            textShadow: `
              0 ${1 * scale}px 0 #ffffff,
              0 -${1 * scale}px 0 #bbbbbb,
              ${1 * scale}px ${1 * scale}px 0 #d0cac0,
              ${2 * scale}px ${2 * scale}px 0 #c4bdb2,
              ${3 * scale}px ${3 * scale}px 0 #b8b1a5,
              ${4 * scale}px ${4 * scale}px 0 #aca598,
              ${5 * scale}px ${8 * scale}px ${15 * scale}px rgba(0,0,0,0.3)
            `,
            transform: `translate(${currentShakeX}px, ${currentShakeY}px) rotate(${currentShakeX * 0.1}deg)`,
            transition: "none",
          }}
        >
          £
        </div>

        {/* Outer Frame with depth bezel and gloss shadows */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            padding: `${12 * scale}px`,
            backgroundColor: "#0d111d",
            border: `${8 * scale}px solid #202b42`,
            borderRadius: `${32 * scale}px`,
            boxShadow: `
              0 ${25 * scale}px ${60 * scale}px rgba(0, 0, 0, 0.75),
              inset 0 ${4 * scale}px ${12 * scale}px rgba(255, 255, 255, 0.08),
              inset 0 -${4 * scale}px ${12 * scale}px rgba(0, 0, 0, 0.5)
            `,
            transition: "none",
          }}
        >
          {digitsArray.map((targetDigit, i) => {
            const isLeading = i < firstNonZeroIndex;

            // Stagger start frame of each drum from left to right
            const drumStartFrame = startFrame + i * 8;
            const currentFrameForDrum = Math.max(0, frame - drumStartFrame);

            // Compute physics-based spring rotation progress (0 to 1)
            const progress = spring({
              frame: currentFrameForDrum,
              fps,
              config: {
                mass: drumMass,
                damping: drumDamping,
                stiffness: drumStiffness + i * 4, // Later drums spin slightly faster to finish cascade
              },
            });

            // Spin configuration: leading zeros do a quick mechanical roll-shake to stay fresh
            const extraRotations = isLeading ? 1 : i - firstNonZeroIndex + 2;
            const finalDigit = isLeading ? 0 : targetDigit;
            const targetAngle = -(extraRotations * 360 + finalDigit * 36);

            // Interpolate dynamic angle
            const angle = interpolate(progress, [0, 1], [0, targetAngle]);

            // Interpolated text color (High-contrast cream or vibrant red on black background)
            const textColor = interpolateColors(
              progress,
              [0, 1],
              ["#ede9e1", isLeading ? "#ede9e1" : "#ff333a"]
            );

            return (
              <div
                key={i}
                style={{
                  position: "relative",
                  width: `${166 * scale}px`,
                  height: `${246 * scale}px`,
                  margin: `0 ${6 * scale}px`,
                  borderRadius: `${18 * scale}px`,
                  backgroundColor: "#000000",
                  overflow: "hidden",
                  boxShadow: `inset 0 ${6 * scale}px ${15 * scale}px rgba(0,0,0,0.95)`,
                  perspective: "900px",
                  transition: "none",
                }}
              >
                {/* 3D Rotating Drum Container */}
                <div
                  style={{
                    position: "absolute",
                    top: "50%",
                    left: "50%",
                    width: "100%",
                    height: `${faceHeight}px`,
                    marginTop: `-${faceHeight / 2}px`,
                    marginLeft: "-50%",
                    transformStyle: "preserve-3d",
                    transform: `rotateX(${angle}deg)`,
                    transition: "none",
                  }}
                >
                  {/* Create all 10 face digits (0-9) around the drum cylinder */}
                  {Array.from({ length: 10 }).map((_, j) => {
                    const faceAngle = j * 36;
                    const totalAngle = angle + faceAngle;
                    const rad = (totalAngle * Math.PI) / 180;
                    const cosVal = Math.cos(rad);

                    // Dynamic opacity calculation to fade numbers gracefully as they roll above/below center
                    const faceOpacity = cosVal > 0 ? Math.max(0.08, Math.pow(cosVal, 3.5)) : 0.08;

                    return (
                      <div
                        key={j}
                        style={{
                          position: "absolute",
                          width: "100%",
                          height: `${faceHeight}px`,
                          left: 0,
                          top: 0,
                          transform: `rotateX(${faceAngle}deg) translateZ(${radius}px)`,
                          backfaceVisibility: "hidden",
                          display: "flex",
                          justifyContent: "center",
                          alignItems: "center",
                          background: `linear-gradient(135deg, #1a1a1a 0%, #000000 100%)`,
                          borderRadius: `${8 * scale}px`,
                          boxShadow: `inset 0 0 ${12 * scale}px rgba(0,0,0,0.4), inset 0 ${1 * scale}px ${2 * scale}px rgba(255,255,255,0.05)`,
                          opacity: faceOpacity,
                          transition: "none",
                        }}
                      >
                        <span
                          style={{
                            fontSize: `${160 * scale}px`,
                            fontWeight: 900,
                            color: textColor,
                            textShadow: getShadowStyle(progress, isLeading),
                            userSelect: "none",
                            lineHeight: 1,
                            marginTop: `-${8 * scale}px`,
                            transition: "none",
                          }}
                        >
                          {j}
                        </span>
                      </div>
                    );
                  })}
                </div>

                {/* Cylinder Shadow Overlay (creates curved lighting effect) */}
                <div
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    width: "100%",
                    height: "100%",
                    background: `linear-gradient(to bottom, 
                      rgba(0,0,0,0.92) 0%, 
                      rgba(0,0,0,0.4) 15%, 
                      rgba(0,0,0,0) 45%, 
                      rgba(0,0,0,0) 55%, 
                      rgba(0,0,0,0.4) 85%, 
                      rgba(0,0,0,0.92) 100%)`,
                    zIndex: 4,
                    pointerEvents: "none",
                    transition: "none",
                  }}
                />

                {/* Horizontal Dividing Seam (Mechanical flip look) */}
                <div
                  style={{
                    position: "absolute",
                    top: "50%",
                    left: 0,
                    width: "100%",
                    height: `${3 * scale}px`,
                    backgroundColor: "rgba(0, 0, 0, 0.45)",
                    zIndex: 5,
                    boxShadow: `0 ${1 * scale}px ${2 * scale}px rgba(0, 0, 0, 0.6)`,
                    pointerEvents: "none",
                    transition: "none",
                  }}
                />
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default RollingCounter;